pub fn prime_num(n: u64) -> bool {
    // Given: n >= 2
    if n <= 3 {
        return true; // 2 and 3 are prime
    }
    if n % 2 == 0 || n % 3 == 0 {
        return false; // eliminates even numbers and multiples of 3
    }

    // Check potential factors of the form 6k ± 1 up to sqrt(n),
    // using d <= n / d to avoid overflow from d*d.
    let mut d: u64 = 5;
    while d <= n / d {
        if n % d == 0 || n % (d + 2) == 0 {
            return false;
        }
        d += 6;
    }
    true
}